function createUsageTracker(limit) {
  let used = 0;                       // private: only the inner functions can see it
  return {
    add(tokens) {
      if (used + tokens > limit) return false;
      used += tokens;
      return true;
    },
    remaining: () => limit - used,
  };
}

const tracker = createUsageTracker(1000);
tracker.add(400);
tracker.add(700);                     // rejected: would exceed the limit
console.log(tracker.remaining());     // 600
console.log(tracker.used);            // undefined

async function sendMessage(text, setLoading) {
  setLoading(true);
  try {
    const res = await fetch('/api/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ message: text }),
    });
    if (!res.ok) throw new Error(`Request failed with ${res.status}`);
    const data = await res.json();
    return data.reply;
  } catch (err) {
    console.error(err.message);
    return 'Sorry, something went wrong.';
  } finally {
    setLoading(false);
  }
}

